  edit("lantern-festival", "blue-center", "A blue centerpiece", [["(0, \"#ee8f7b\")", "(0, \"#86b9e7\")"]], "Change one color in the row’s data.", "The middle lantern is blue; all four neighbors keep their colors.", "Swap the colors at the two ends.", ["(0, \"#86b9e7\")"], {"syntax": "(0, \"#86b9e7\")", "assertOutput": []});
  edit("boat-hull", "teal", "A teal hull", [["color(\"#e58b70\")", "color(\"#418f91\")"]], "Recolor the hull while keeping the sail.", "The boat has a teal hull and a cream sail.", "Try a dark hull and compare its contrast.", ["color(\"#418f91\")"], {"syntax": "color(\"#418f91\")", "assertOutput": []});
  edit("boat-scale", "full-size", "A full-size fold", [["size = 0.7", "size = 1.0"]], "Change the one shared scale value.", "The boat returns to its original width and height.", "Compare size 0.5 with size 1.0.", ["size = 1.0"], {"syntax": "size = 1.0", "assertOutput": []});
